head.r/main.tf:
terraform {
  backend "s3" {}
}
variable "env" {
  default = "prod"
}
variable "n" {
  default = 5
}
variable "on" {
  default = false
}
variable "u" {}
variable "missing" {
  default = {}
}
variable "l" {
  default = [{ n = 1 }, { n = 2 }]
}
resource "aws_s3_bucket" "b" {
  bucket = "exports-prod"
}
resource "terraform_data" "out" {
  input = {
    tpl            = "acme-${var.env}"
    single_num     = "${var.n}"
    bucket_arg     = aws_s3_bucket.b.bucket
    json_known     = jsonencode({ a = 1 })
    for_list       = [for s in ["a", "b"] : upper(s) if s != "b"]
    for_map        = { for k, v in { x = 1 } : k => v * 2 }
    cond           = var.on ? "yes" : "no"
    coal           = coalesce(null, "", "z")
    lkp            = lookup({ a = 1 }, "b", 7)
    fmt            = format("%s-%d", "q", 3)
    merged         = merge({ a = 1 }, { b = 2 })
    set_val        = toset(["b", "a", "b"])
    subnet         = cidrsubnet("10.0.0.0/16", 8, 2)
    try_fallback   = try(var.missing.x, "fallback")
    equal_branches = var.u ? "same" : "same"
    len_with_u     = length([var.u, 2])
    keys_with_u    = keys({ k = var.u })
    try_bad_json   = try(jsondecode(""), {})
    try_named_re   = try(regex("(?P<n>a)", "a"), "x")
    try_icase_re   = try(regex("(?i)ABC", "abc"), "no")
    try_bad_re     = try(regex("([", "a"), "bad-regex")
    splat_list     = var.l[*].n
  }
}

