terraform {
  backend "s3" {}
}
variable "region" {}
variable "acct" {}
variable "mod_out" {}
resource "aws_s3_bucket" "b" {
  bucket = "exports-prod"
}
resource "aws_s3_bucket" "config" {
  bucket = "config-prod"
}
resource "aws_sns_topic" "t" {
  name = "events"
}
resource "aws_iam_policy" "tenant_wildcard" {
  name   = "p1"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "secretsmanager:GetSecretValue", Resource = "arn:aws:secretsmanager:${var.region}:${var.acct}:secret:provider/*/api-credentials-??????" }] })
}
resource "aws_iam_policy" "bucket_objects" {
  name   = "p2"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = ["s3:GetObject"], Resource = "${aws_s3_bucket.b.arn}/*" }] })
}
resource "aws_iam_policy" "topic_arn" {
  name   = "p3"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sns:Publish", Resource = aws_sns_topic.t.arn }] })
}
resource "aws_iam_policy" "unknown_shape" {
  name   = "p4"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "secretsmanager:GetSecretValue", Resource = var.mod_out }] })
}
resource "aws_iam_policy" "fixed_secret" {
  name   = "p5"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "secretsmanager:GetSecretValue", Resource = "arn:aws:secretsmanager:${var.region}:${var.acct}:secret:jev/api-key-??????" }] })
}
resource "aws_iam_policy" "subpath_object" {
  name   = "p6"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = ["s3:GetObject"], Resource = "${aws_s3_bucket.config.arn}/gateway/otel.yaml" }] })
}
resource "aws_iam_policy" "ecs_exec" {
  name   = "p7"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = ["ssmmessages:CreateControlChannel", "ssmmessages:CreateDataChannel", "ssmmessages:OpenControlChannel", "ssmmessages:OpenDataChannel"], Resource = "*" }] })
}

terraform {
  backend "s3" {}
}
variable "eff" {}
variable "extra_stmt" {}
variable "vpce_id" {}
variable "secret_policy" {
  sensitive = true
}
resource "aws_iam_role" "org_not_eq" {
  name               = "r1"
  assume_role_policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sts:AssumeRoleWithWebIdentity", Principal = "*", Condition = { StringNotEquals = { "aws:PrincipalOrgID" = "o-123" } } }] })
}
resource "aws_iam_role" "org_eq" {
  name               = "r2"
  assume_role_policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sts:AssumeRoleWithWebIdentity", Principal = "*", Condition = { StringEquals = { "aws:PrincipalOrgID" = "o-123" } } }] })
}
resource "aws_iam_role" "gh_not_like" {
  name               = "r3"
  assume_role_policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sts:AssumeRoleWithWebIdentity", Principal = { Federated = "arn:aws:iam::1:oidc-provider/token.actions.githubusercontent.com" }, Condition = { StringEquals = { "token.actions.githubusercontent.com:aud" = "sts.amazonaws.com" }, StringNotLike = { "token.actions.githubusercontent.com:sub" = "repo:evil/*" } } }] })
}
resource "aws_iam_role" "org_wildcard" {
  name               = "r4"
  assume_role_policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sts:AssumeRoleWithWebIdentity", Principal = "*", Condition = { StringLike = { "aws:PrincipalOrgID" = "*" } } }] })
}
resource "aws_iam_role" "org_if_exists" {
  name               = "r5"
  assume_role_policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sts:AssumeRoleWithWebIdentity", Principal = "*", Condition = { StringEqualsIfExists = { "aws:PrincipalOrgID" = "o-123" } } }] })
}
resource "aws_iam_role" "unknown_effect" {
  name               = "r6"
  assume_role_policy = jsonencode({ Statement = [{ Effect = var.eff, Action = "sts:AssumeRole", Principal = "*" }] })
}
resource "aws_iam_role" "not_principal" {
  name               = "r7"
  assume_role_policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "sts:AssumeRole", NotPrincipal = { AWS = "arn:aws:iam::111122223333:role/x" } }] })
}
resource "aws_iam_policy" "sensitive_unknown" {
  name   = "p_sens"
  policy = var.secret_policy
}
resource "aws_iam_policy" "unknown_stmt_member" {
  name   = "p_mem"
  policy = jsonencode({ Statement = concat([{ Effect = "Allow", Action = "s3:GetObject", Resource = "arn:aws:s3:::b/*" }], [var.extra_stmt]) })
}
resource "aws_s3_bucket_policy" "secure_transport_only" {
  bucket = "b1"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b1/*", Condition = { Bool = { "aws:SecureTransport" = "true" } } }] })
}
resource "aws_s3_bucket_policy" "vpce_scoped" {
  bucket = "b2"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b2/*", Condition = { StringEquals = { "aws:SourceVpce" = "vpce-1" } } }] })
}
resource "aws_s3_bucket_policy" "vpce_unknown_exact" {
  bucket = "b3"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b3/*", Condition = { StringEquals = { "aws:SourceVpce" = var.vpce_id } } }] })
}
resource "aws_s3_bucket_policy" "wide_cidrs" {
  bucket = "b4"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b4/*", Condition = { IpAddress = { "aws:SourceIp" = ["0.0.0.0/1", "128.0.0.0/1"] } } }] })
}
resource "aws_s3_bucket_policy" "narrow_cidr" {
  bucket = "b5"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b5/*", Condition = { IpAddress = { "aws:SourceIp" = "203.0.113.0/24" } } }] })
}
resource "aws_s3_bucket_policy" "arn_equals_wildcard" {
  bucket = "b6"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b6/*", Condition = { ArnEquals = { "aws:PrincipalArn" = "arn:aws:iam::*:*" } } }] })
}
resource "aws_s3_bucket_policy" "arn_equals_exact" {
  bucket = "b7"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b7/*", Condition = { ArnEquals = { "aws:PrincipalArn" = "arn:aws:iam::111122223333:role/x" } } }] })
}
resource "aws_s3_bucket_policy" "org_prefix_wildcard" {
  bucket = "b8"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b8/*", Condition = { StringLike = { "aws:PrincipalOrgID" = "o-*" } } }] })
}
resource "aws_s3_bucket_policy" "anded_operators" {
  bucket = "b9"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b9/*", Condition = { StringEquals = { "aws:SourceAccount" = "111122223333" }, StringLike = { "aws:SourceAccount" = "*" } } }] })
}
